<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';import {request} from '../../api/client';import {all,message} from '../sites/data';import type {Site} from '../sites/contracts';
const sites=ref<Site[]>([]),selected=ref<string[]>([]),source=ref('archive'),from=ref(new Date(Date.now()-3600000).toISOString().slice(0,16)),to=ref(new Date().toISOString().slice(0,16)),route=ref(''),method=ref(''),status=ref(0),jobs=ref<any[]>([]),page=ref<any>(),offset=ref(0),error=ref(''),busy=ref(false),notice=ref('');const hasMore=ref(false),nextOffset=ref(0);let timer:ReturnType<typeof setInterval>|undefined,alive=true;
async function list(){jobs.value=[];hasMore.value=false;nextOffset.value=0;const v=await request<any>('/log-queries?limit=25&offset='+offset.value);if(alive){jobs.value=v.items||[];hasMore.value=v.has_more===true;nextOffset.value=v.next_offset||0}}
async function run(fn:()=>Promise<void>){error.value='';busy.value=true;try{await fn()}catch(e){page.value=undefined;jobs.value=[];hasMore.value=false;nextOffset.value=0;error.value=message(e)}finally{busy.value=false}}
async function fetchJob(id:string,cursor=''){page.value=undefined;const v=await request<any>('/log-queries/'+encodeURIComponent(id)+'?cursor='+encodeURIComponent(cursor));if(alive)page.value=v}
async function submit(){await run(async()=>{const j=await request<any>('/log-queries',{source:source.value,SiteIDs:selected.value,From:new Date(from.value+'Z').toISOString(),To:new Date(to.value+'Z').toISOString(),Route:route.value,Method:method.value,Status:Number(status.value)});await fetchJob(j.ID);await list()})}
async function cancel(){if(!page.value)return;const id=page.value.Job.ID;await run(async()=>{await request('/log-queries/'+id+'/cancel',{});await fetchJob(id);await list()})}
async function download(){if(!page.value)return;await run(async()=>{const rows=await request<any[]>('/log-queries/'+page.value.Job.ID+'/download');const url=URL.createObjectURL(new Blob([JSON.stringify(rows)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='gatebeam-logs.json';a.click();URL.revokeObjectURL(url);notice.value='已下载服务端再次验权后的有界结果；覆盖范围见任务清单。'})}
async function refresh(){await run(async()=>{const id=page.value?.Job.ID;await list();if(id)await fetchJob(id)})}
onMounted(()=>{void run(async()=>{sites.value=await all<Site>('/sites');await list()});timer=setInterval(()=>{if(!busy.value&&['queued','running','coordinating'].includes(page.value?.Job.State))void refresh()},1000)});onUnmounted(()=>{alive=false;if(timer)clearInterval(timer);page.value=undefined;jobs.value=[]});
</script>
<template><section><h1>历史日志</h1><p class="muted">仅覆盖冻结清单；本地与 R2 归档分别查询，均可能缺少尚未采集或尚未归档数据。最多 31 天、4096 对象、2 GiB 扫描、10000 行；超限会失败，不显示全量成功。</p><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><section class="panel"><label v-for="s in sites" :key="s.id" class="check"><input type="checkbox" v-model="selected" :value="s.id">{{s.name}}</label><label>数据来源<select v-model="source"><option value="archive">R2 已归档</option><option value="local">本地已持久化 Parquet</option></select></label><label>日志开始（UTC）<input type="datetime-local" v-model="from"></label><label>日志结束（UTC）<input type="datetime-local" v-model="to"></label><label>固定路由编号<input v-model="route"></label><label>方法<select v-model="method"><option value="">全部</option><option>GET</option><option>POST</option><option>HEAD</option></select></label><label>状态码（0 为全部）<input type="number" v-model="status"></label><button @click="submit" :disabled="busy||!selected.length">提交历史查询</button></section><section class="panel" v-if="page" data-testid="log-result"><h2>任务结果</h2><p class="mono">{{page.Job.ID}}</p><p role="status">{{page.Job.State}} · {{page.Job.Error||'无错误回执'}}</p><p>覆盖 {{page.Job.Coverage}} · 冻结清单水位 {{page.Job.Watermark}} · 对象 {{page.Job.ManifestObjects}} · 扫描 {{page.Job.ScanBytes}} 字节</p><p>部分覆盖，不能认定全量；{{page.Job.Truncated?'达到行数上限，请缩小范围':'仅返回已冻结对象的匹配行'}}。到期 {{page.Job.ExpiresAt}}</p><button @click="refresh" :disabled="busy">刷新任务</button><button @click="cancel" :disabled="busy||!['queued','running','coordinating'].includes(page.Job.State)">取消任务</button><button @click="download" :disabled="busy||page.Job.State!=='succeeded'">下载已授权结果</button><table><thead><tr><th>时间 / 请求</th><th>节点 / 站点 / 路由</th><th>方法 / 状态</th><th>耗时 μs</th></tr></thead><tbody><tr v-for="(row,i) in page.Rows" :key="i"><td>{{row.time}}<br>{{row.request_id}}</td><td>{{row.node_id||'legacy'}}<br>{{row.site_id}} / {{row.route}}</td><td>{{row.method}} {{row.status}}</td><td>{{row.request_micros}}</td></tr></tbody></table><button v-if="page.Cursor" :disabled="busy" @click="run(()=>fetchJob(page.Job.ID,page.Cursor))">下一页结果</button></section><section class="panel"><h2>我的查询任务</h2><p>最近 10 分钟的持久任务；每次读取及下载均重新核对当前凭据和站点。</p><p v-for="j in jobs" :key="j.ID"><button @click="run(()=>fetchJob(j.ID))">{{j.ID}}</button> {{j.State}} {{j.Error}}</p><button @click="refresh" :disabled="busy">刷新任务列表</button><button :disabled="busy||offset===0" @click="offset-=25;refresh()">上一页任务</button><button :disabled="busy||!hasMore" @click="offset=nextOffset;refresh()">下一页任务</button></section></section></template>
